import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"技术栈与版本兼容表","description":"汇总 TS-AI 全栈手册约定主线：运行时、NestJS、LangChain.js / LangGraph.js、Nuxt、数据与观测栈的版本核对原则","frontmatter":{"title":"技术栈与版本兼容表","description":"汇总 TS-AI 全栈手册约定主线：运行时、NestJS、LangChain.js / LangGraph.js、Nuxt、数据与观测栈的版本核对原则","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/references/technology-stack-compatibility.md","filePath":"ts-ai/appendix/references/technology-stack-compatibility.md","lastUpdated":1786113687000}'),o={name:"ts-ai/appendix/references/technology-stack-compatibility.md"};function n(s,t,i,c,h,l){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="技术栈与版本兼容表" tabindex="-1">技术栈与版本兼容表 <a class="header-anchor" href="#技术栈与版本兼容表" aria-label="Permalink to &quot;技术栈与版本兼容表&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本表固定<strong>本手册约定主线</strong>，方便选型、升级与排障时对齐边界。表中的 semver 区间是写作时的合理主流线，<strong>不是</strong>对某一 patch 的精确承诺；落地以<strong>官方文档当前要求</strong>与项目 <strong>lockfile</strong> 为准。</p><p>包分层与导入边界见 <a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态、包与版本边界</a>；可点击官方文档入口见 <a href="/ts-ai/appendix/references/official-resources">官方资料索引</a>。</p><h2 id="_1-怎么用这张表" tabindex="-1">1. 怎么用这张表 <a class="header-anchor" href="#_1-怎么用这张表" aria-label="Permalink to &quot;1. 怎么用这张表&quot;">​</a></h2><h3 id="_1-1-字段含义" tabindex="-1">1.1 字段含义 <a class="header-anchor" href="#_1-1-字段含义" aria-label="Permalink to &quot;1.1 字段含义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>组件</td><td>手册默认依赖或运行时</td></tr><tr><td>约定主线</td><td>示例与项目篇默认对齐的大版本 / 主线</td></tr><tr><td>核对原则</td><td>升级或排障时优先检查什么</td></tr><tr><td>手册落点</td><td>负责讲解该组件边界的章节</td></tr></tbody></table><h3 id="_1-2-核对原则-全局" tabindex="-1">1.2 核对原则（全局） <a class="header-anchor" href="#_1-2-核对原则-全局" aria-label="Permalink to &quot;1.2 核对原则（全局）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>以官方为准</td><td>引擎要求、破坏性变更以官方安装说明 / Changelog 为准</td></tr><tr><td>以 lockfile 为准</td><td>CI、本地、容器使用同一锁文件解析结果；勿口头约定 patch</td></tr><tr><td>单实例对齐</td><td><code>@langchain/core</code>、Nest 与前端 peer 依赖避免双实例</td></tr><tr><td>先最小再全栈</td><td>升级后先跑模块内最小骨架，再回归五个实战项目</td></tr><tr><td>不跨主线混装</td><td>不要把旧单体 <code>langchain</code> 导入路径与新多包入口混在同一模块</td></tr></tbody></table><h3 id="_1-3-本表不负责什么" tabindex="-1">1.3 本表不负责什么 <a class="header-anchor" href="#_1-3-本表不负责什么" aria-label="Permalink to &quot;1.3 本表不负责什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不覆盖</th><th>去哪里</th></tr></thead><tbody><tr><td>具体 API 签名</td><td><a href="/ts-ai/appendix/api-index/">API 索引</a></td></tr><tr><td>外部 Demo 仓库版本</td><td>本手册不维护平行 Demo 宇宙；示例见 <a href="/ts-ai/appendix/references/examples-index">示例项目索引</a></td></tr><tr><td>云厂商私有 SDK 全表</td><td>只保证 OpenAI 兼容主线可替换</td></tr></tbody></table><h2 id="_2-运行时与语言" tabindex="-1">2. 运行时与语言 <a class="header-anchor" href="#_2-运行时与语言" aria-label="Permalink to &quot;2. 运行时与语言&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>约定主线</th><th>核对原则</th><th>手册落点</th></tr></thead><tbody><tr><td>Node.js</td><td><strong>22+</strong>（LTS 主线）</td><td><code>engines.node</code>、CI 镜像与本机主版本一致；LangChain.js 官方安装说明要求 22+</td><td><a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a></td></tr><tr><td>TypeScript</td><td><strong>5.x</strong></td><td><code>module</code>/<code>moduleResolution</code> 与 ESM 一致；<code>strict</code> 足以跑通示例即可</td><td>同上</td></tr><tr><td>包管理器</td><td><strong>pnpm</strong>（推荐）或 npm</td><td>提交锁文件；勿在 CI 用不同管理器重算树</td><td>工程模板见附录模板分组</td></tr><tr><td>Zod</td><td><strong>3.x 主线</strong>（以 lockfile 为准）</td><td>Schema 用于环境变量、DTO、工具参数、结构化输出；升级大版本时回归 <code>safeParse</code></td><td><a href="/ts-ai/foundations/getting-started/zod-minimum-introduction">Zod 最小入门</a></td></tr><tr><td>Vitest</td><td><strong>当前稳定主线</strong></td><td>单元 / 集成测与 Fake 模型共用；版本以 lockfile 为准</td><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用的 Fake、Mock 与错误测试</a></td></tr></tbody></table><h2 id="_3-后端与数据" tabindex="-1">3. 后端与数据 <a class="header-anchor" href="#_3-后端与数据" aria-label="Permalink to &quot;3. 后端与数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>约定主线</th><th>核对原则</th><th>手册落点</th></tr></thead><tbody><tr><td>NestJS</td><td><strong>10.x / 11.x 主线</strong>（项目篇写作时常写 10+）</td><td>全局 ValidationPipe、Module 边界、SSE 适配器行为；以官方 docs 与 lockfile 为准</td><td><a href="/ts-ai/backend/nestjs-core/">NestJS 核心</a></td></tr><tr><td>PostgreSQL</td><td><strong>16.x 主线</strong></td><td>Thread/Run/Message 真相源；迁移可重复执行</td><td><a href="/ts-ai/backend/data-tasks/postgresql-orm-migrations">PostgreSQL、ORM 与迁移</a></td></tr><tr><td>pgvector</td><td><strong>与 PG 16 兼容的扩展主线</strong></td><td>向量维度、索引类型与 Embedding 模型一致</td><td><a href="/ts-ai/knowledge/retrieval/postgresql-pgvector">PostgreSQL 与 pgvector</a></td></tr><tr><td>Redis</td><td><strong>7.x 主线</strong></td><td>只放缓存 / 锁 / 限流 / 短缓冲；不是业务真相源</td><td><a href="/ts-ai/backend/data-tasks/redis-state-ownership">Redis 与状态所有权</a></td></tr><tr><td>BullMQ</td><td><strong>5.x 主线</strong>（以 lockfile 为准）</td><td>Job 幂等键、重试与取消和 Run 状态对齐</td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ 与可靠 Worker</a></td></tr><tr><td>ORM / 迁移</td><td><strong>团队选定的 Nest 友好 ORM 主线</strong></td><td>迁移可回放；勿把向量索引当普通列随意改</td><td>同上 PostgreSQL 篇</td></tr></tbody></table><h2 id="_4-ai-编排包" tabindex="-1">4. AI 编排包 <a class="header-anchor" href="#_4-ai-编排包" aria-label="Permalink to &quot;4. AI 编排包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>约定主线</th><th>核对原则</th><th>手册落点</th></tr></thead><tbody><tr><td><code>@langchain/core</code></td><td><strong>与同树 langchain / 供应商包同一主线</strong></td><td><code>pnpm why @langchain/core</code> 只能有一份有效解析；Message / Runnable 只从 core 导入</td><td><a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态、包与版本边界</a></td></tr><tr><td><code>langchain</code></td><td><strong>1.x / 当前稳定主线（v1）</strong>；以官方安装说明与 lockfile 为准。<strong>不要</strong>再按历史「0.3+」主线选型——0.3 时代常见的是 <code>createReactAgent</code> 等旧入口，本手册默认的 <code>createAgent</code> / <code>fakeModel()</code> 属于 v1</td><td><code>createAgent</code>、<code>tool</code>、<code>fakeModel</code> 等高层入口；勿混用废弃路径</td><td><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a></td></tr><tr><td><code>@langchain/openai</code></td><td><strong>与 core 对齐的当前主线</strong></td><td><code>ChatOpenAI</code>、Embeddings；兼容网关时仍用 OpenAI 协议形状</td><td><a href="/ts-ai/agent/langchain-core/chat-model-chatopenai">ChatModel 与 ChatOpenAI</a></td></tr><tr><td><code>@langchain/langgraph</code></td><td><strong>当前稳定主线</strong></td><td>Checkpoint、Interrupt、多 Agent 图；State 迁移单独回归。<code>@langchain/langgraph/prebuilt</code> 的 <code>createReactAgent</code> 仅作 supervisor/swarm 示意遗留入口，<strong>不是</strong>手册主线 Agent API</td><td><a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a>；多 Agent 边界见 <a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor</a></td></tr><tr><td><code>@langchain/langgraph-supervisor</code></td><td><strong>按官方 README 钉版本使用（进阶）</strong></td><td>历史示意常搭配 <code>createReactAgent</code>；生产优先 <code>createAgent</code> 基线，再核对 <code>agents</code> 是否接受该产物，勿静默互换工厂</td><td><a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor 与 Handoff</a></td></tr><tr><td><code>@langchain/langgraph-swarm</code></td><td><strong>按官方 README 钉版本使用（进阶）</strong></td><td>同上：官方常更稳妥搭配 <code>createReactAgent</code>；与 <code>createAgent</code> 组合需自行验证版本矩阵</td><td><a href="/ts-ai/workflow/multi-agent/network-swarm">Network 与 Swarm</a></td></tr><tr><td><code>@modelcontextprotocol/sdk</code></td><td><strong>当前稳定主线</strong></td><td>传输、鉴权与工具 Schema；网关白名单独立验收</td><td><a href="/ts-ai/agent/tools-mcp/mcp-typescript-sdk">MCP 与 TypeScript SDK</a></td></tr><tr><td><code>@langchain/mcp-adapters</code></td><td><strong>与 langchain / MCP SDK 对齐的当前主线</strong></td><td>远程工具与本地 Tool 合流后的权限与审计</td><td><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></td></tr><tr><td>OpenAI API / 兼容端点</td><td><strong>Chat Completions + Tools 主线</strong></td><td>Base URL、模型名、限流与错误码；密钥不出浏览器</td><td><a href="/ts-ai/foundations/model/model-request-response-errors">模型请求、响应与错误</a></td></tr></tbody></table><h2 id="_5-前端主线与扩展" tabindex="-1">5. 前端主线与扩展 <a class="header-anchor" href="#_5-前端主线与扩展" aria-label="Permalink to &quot;5. 前端主线与扩展&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>约定主线</th><th>核对原则</th><th>手册落点</th></tr></thead><tbody><tr><td>Vue 3</td><td><strong>3.x</strong></td><td>Composition API、响应式边界；不把 Run 真相放前端</td><td><a href="/ts-ai/integration/vue-nuxt/">Vue 3 与 Nuxt</a></td></tr><tr><td>Nuxt</td><td><strong>3.x / 4.x 主线中与手册示例一致的一支</strong>（以 lockfile 为准）</td><td>SSR/Hydration 与客户端 Chat 状态分离；BFF 保持薄</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">Nuxt AI 项目结构</a></td></tr><tr><td>自建 SSE 协议</td><td><strong>手册事件契约</strong>（非厂商私有流协议）</td><td><code>Last-Event-ID</code>、取消、去重与 Run 状态一致</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP、SSE 与 WebSocket</a></td></tr><tr><td>React / Next.js</td><td><strong>扩展线</strong>（非默认交付）</td><td>状态模型对照后迁移；不默认替换 Nuxt 主线</td><td><a href="/ts-ai/integration/react-next/">React 与 Next.js 扩展</a></td></tr><tr><td>Vercel AI SDK</td><td><strong>可选扩展</strong></td><td>仅在扩展章节使用；主线仍是自建 SSE ↔ Nest</td><td><a href="/ts-ai/integration/vue-nuxt/ai-sdk-vue-integration">AI SDK Vue 集成</a></td></tr></tbody></table><h2 id="_6-观测与部署" tabindex="-1">6. 观测与部署 <a class="header-anchor" href="#_6-观测与部署" aria-label="Permalink to &quot;6. 观测与部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>约定主线</th><th>核对原则</th><th>手册落点</th></tr></thead><tbody><tr><td>结构化日志</td><td><strong>JSON 行日志 + 关联 ID</strong></td><td><code>requestId</code> / <code>runId</code> / <code>tenantId</code> 可串联</td><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></td></tr><tr><td>OpenTelemetry</td><td><strong>JS SDK 当前稳定主线</strong></td><td>Trace 与日志关联；导出器与采样策略可配置</td><td><a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OpenTelemetry 接线与 LangSmith 关联</a></td></tr><tr><td>LangSmith（可选）</td><td><strong>当前云端 / 自托管主线</strong></td><td>密钥与采样；评测实验与生产 Trace 分离</td><td>同上；评测见 <a href="/ts-ai/quality/testing-evaluation/langsmith-evaluation">评测实验与 LangSmith</a></td></tr><tr><td>Docker</td><td><strong>多阶段构建当前实践</strong></td><td>健康检查、优雅关闭、非 root 运行</td><td><a href="/ts-ai/quality/deployment-operations/docker">Docker</a></td></tr><tr><td>CI/CD</td><td><strong>锁文件安装 + 类型检查 + 测试 + 构建</strong></td><td>Node 主版本与生产一致；Secret 不进镜像层</td><td><a href="/ts-ai/quality/deployment-operations/ci-cd">CI/CD</a></td></tr></tbody></table><h2 id="_7-升级核对清单" tabindex="-1">7. 升级核对清单 <a class="header-anchor" href="#_7-升级核对清单" aria-label="Permalink to &quot;7. 升级核对清单&quot;">​</a></h2><p>升级任一主线依赖前，按顺序勾选：</p><table tabindex="0"><thead><tr><th>#</th><th>检查项</th><th>通过标准</th></tr></thead><tbody><tr><td>1</td><td>阅读官方 Changelog / 迁移说明</td><td>已知破坏性变更与引擎要求</td></tr><tr><td>2</td><td>对齐 <code>@langchain/core</code> 单实例</td><td><code>pnpm why</code> / 等价命令只见一条有效解析</td></tr><tr><td>3</td><td>跑 <a href="/ts-ai/appendix/references/examples-index#2-模块内最小骨架">模块内最小骨架</a></td><td>类型检查与最小 invoke / HTTP / 图编译通过</td></tr><tr><td>4</td><td>回归 <a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td><td>SSE、取消、重连、鉴权租户仍绿</td></tr><tr><td>5</td><td>按路径回归后续项目</td><td>RAG / 工作流 / MCP 中实际用到的路径</td></tr><tr><td>6</td><td>复查观测与密钥</td><td>Trace 不断链；Secret 未泄漏到前端或日志正文</td></tr><tr><td>7</td><td>提交 lockfile</td><td>CI 与本地解析树一致</td></tr></tbody></table><h2 id="_8-关联章节" tabindex="-1">8. 关联章节 <a class="header-anchor" href="#_8-关联章节" aria-label="Permalink to &quot;8. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>章节</th></tr></thead><tbody><tr><td>包导入与冲突排查</td><td><a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态、包与版本边界</a></td></tr><tr><td>官方文档入口</td><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td></tr><tr><td>可运行示例路径</td><td><a href="/ts-ai/appendix/references/examples-index">示例项目索引</a></td></tr><tr><td>框架边界 ADR</td><td><a href="/ts-ai/architecture/design-decisions/framework-selection-adr">框架选型与 ADR</a></td></tr><tr><td>发布与运维</td><td><a href="/ts-ai/architecture/delivery/release-checklist">发布清单</a></td></tr></tbody></table>',26)])])}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
